    "gbif_id": 9797180,
    "inat_id": 4954,
    "categories": [
      "OFF_TUSKS_PIERCERS",
      "SENS_EXTREME_SENSORY"
    ],
    "cat_curiosities": {
      "OFF_TUSKS_PIERCERS": "Il lungo becco appuntito funziona come un arpione: scatta in avanti col collo a scatto per infilzare o afferrare pesci, rane e piccoli mammiferi.",
      "SENS_EXTREME_SENSORY": "Una vista acuta gli fa individuare i pesci sotto la superficie e correggere la rifrazione dell'acqua, dosando con precisione il colpo del becco."
    },
